  ["FULL_TEXT_COMBATLOG_TOOLTIP"] = { "Mostra il registro di combattimento con frasi intere.", 0xbe1cba5d, "." },
  ["FXAA_CMAA_LABEL"] = { "Tecniche basate su immagini", 0xe9dab29f, "." },
  ["FX_VOLUME"] = { "Effetti", 0xf6f9bfd5, "." },
  ["FactionDescription:21"] = { "Questa fiorente città di mare è amministrata dal Barone Revilgaz degli Incursori di Acquanera. Fa parte del Cartello degli Spargifumo ed è nemica mortale dei Bucanieri Velerosse.", 0x7e9b81b0, "." },
  ["FactionDescription:2586"] = { "Fondata in origine per agevolare i commerci nei Regni Orientali, l'ACA ora gestisce le linee di rifornimento delle forze dell'Alleanza in tutto il mondo.", 0x8036c9b7, "." },
  ["FactionDescription:2587"] = { "La solida rete di rifornimenti dell'Orda alimenta la sua rapida espansione in tutto Kalimdor e oltre.", 0xd5dd6387, "." },
  ["FactionDescription:2634"] = { "Il cielo è rosso e i tuoi sensi sono sopraffatti dalla sete di sangue!", 0x81534b1e, "." },
  ["FactionDescription:2641"] = { "Un gruppo di druidi organizzato in fretta, che collabora con l'Alleanza e con l'Orda per fermare le Incursioni dell'Incubo.", 0x5bdc18b7, "." },
  ["FactionDescription:2679"] = { "Un ordine monastico di guerrieri sacri votati al servizio del re di Lordaeron.", 0x40c7b261, "." },
  ["FactionDescription:270"] = { "Questi Troll sono giunti sull'Isola di Yojamba nel tentativo di cercare aiuto per affrontare il Dio del Sangue e i suoi sacerdoti Atal'ai a Zul'gurub.", 0x407992c7, "." },
  ["FactionDescription:2719"] = { "I Cenarion Scouts sono giovani appassionati della natura che si dedicano a esplorare e proteggere le terre selvagge di Azeroth.", 0x44ac6d4a, "." },
  ["FactionDescription:2740"] = { "Una cerchia scelta dei maghi più potenti del mondo e il conclave di maghi che governa la nazione magica di Dalaran.", 0x7a314310, "." },
  ["FactionDescription:2747"] = { "I Barkskin sono tra le poche tribù di mezzorsi non toccate dalla corruzione e si dedicano a custodire il loro retaggio spirituale per riportare l'armonia su Hyjal.", 0xcc6cd07b, "." },
  ["FactionDescription:2758"] = { "I misteriosi druidi di Shadowgale Forest. Agiscono in modo indipendente, separati da ogni altra fazione di Zephras Isle.", 0xb676b03d, "." },
  ["FactionDescription:2765"] = { "Incaricata di proteggere e preservare il Monte Hyjal, questa fazione separatasi dal Circolo Cenariano accoglie chiunque sia disposto a respingere le forze del male.", 0x98a4e7bf, "." },
  ["FactionDescription:2778"] = { "I Windshapers sono le guide spirituali sciamaniche del popolo Skyborne di Zephras Isle. Onorano gli elementi e cercano di comprendere meglio la natura del piano elementale per proteggere lo stile di vita degli shen'dorei a Skywall.", 0x79baf3bf, "." },
  ["FactionDescription:2779"] = { "L'High Order è formato dai discendenti Skyborne dei magistri degli Alti Nobili di Eldre'Thalas. Dopo aver trascorso gli ultimi 10.000 anni nel regno di Skywall, i membri dell'High Order cercano di recuperare l'antico sapere arcano dei loro antenati.", 0xdb7a7bd9, "." },
  ["FactionDescription:2782"] = { "Esiliati per aver tradito i loro falsi profeti, questi ex membri del Martello del Crepuscolo cercano di tracciare la propria strada.", 0xb0d166e2, "." },
  ["FactionDescription:2787"] = { "L'Earthen Ring è un'alleanza informale di sciamani e druidi vicini all'Orda che cercano di mantenere e coltivare l'equilibrio della natura su Azeroth.", 0x3293070e, "." },
  ["FactionDescription:2797"] = { "Membri d'élite della società degli elfi della notte.", 0xd684bc84, "." },
  ["FactionDescription:2798"] = { "Fedeli alla nazione dei troll, i Darkspear Raiders combattono la Theramore Expeditionary Force per il controllo delle loro ancestrali Isole dei Lanciascura.", 0xae4311e4, "." },
  ["FactionDescription:2799"] = { "Partigiani fedeli alla loro città, la Theramore Expeditionary Force combatte i Darkspear Raiders per il controllo delle cosiddette Isole dei Lanciascura.", 0x1bb82cf1, "." },
  ["FactionDescription:2819"] = { "Un ordine di potenti carcerieri e marescialli della società degli elfi della notte. Vigilano perché nessuna minaccia possa mai fuggire dalla loro vasta rete di prigioni sotterranee.", 0x56b24689, "." },
  ["FactionDescription:2826"] = { "Membri emarginati della cavalleria di Roccavento, questi ex cavalieri hanno ricominciato da capo nelle terre inesplorate lungo la costa orientale, dove hanno fondato la loro casa, stretto nuovi rapporti e aperto rotte commerciali.", 0xd6617460, "." },
  ["FactionDescription:2827"] = { "Braccio forte del Cartello degli Spargifumo, questo porto ospita marinai d'alto mare e trafficanti di vicolo che percorrono le rotte commerciali del mare orientale.", 0xcf8710c6, "." },
  ["FactionDescription:349"] = { "Questa gilda di ladri e assassini accetta tra le proprie file soltanto coloro che sono dotati di eccezionali capacità. Nemici giurati della Lega dei Tagliagole.", 0xe15addc5, "." },
  ["FactionDescription:369"] = { "Capitale del Cartello degli Spargifumo e patria dei migliori ingegneri, alchimisti e mercanti Goblin.", 0x6bc27bf5, "." },
  ["FactionDescription:47"] = { "Questa capitale dell'Alleanza è l'orgoglio dei Nani di Dun Morogh, ed è la dimora dei Re dei Nani.", 0x7338a738, "." },
  ["FactionDescription:470"] = { "Questa cittadina Goblin, controllata dal Cartello degli Spargifumo, rappresenta un porto sicuro per tutti coloro che desiderano commerciare nelle Savane.", 0xd92b7fb2, "." },
  ["FactionDescription:471"] = { "Pur non facendo parte dell'Alleanza, i nani del Picco dell'Aquila le hanno aperto le loro porte e considerano l'Orda loro nemica.", 0xff3c6dd2, "." },
  ["FactionDescription:509"] = { "La Lega di Arathor ha come obiettivo quello di reclamare le terre perdute del Bacino d'Arathi per i loro benefattori di Roccavento.", 0x1ec818e3, "." },
  ["FactionDescription:510"] = { "I Profanatori stanno cercando di impossessarsi delle preziose risorse del Bacino di Arathi per conto dell'Orda.", 0x0a18bac0, "." },
  ["FactionDescription:529"] = { "Un'organizzazione dedita alla protezione di Azeroth dalla minaccia del Flagello. Roccaforti dell'Alba d'Argento occupano le Terre Infette Orientali e Occidentali.", 0x4113163d, "." },
  ["FactionDescription:530"] = { "Questa tribù di Troll in esilio ha unito le proprie forze a quelle di Thrall e dell'Orda. Durotar è ora la loro patria, che condividono insieme ai loro alleati Orchi.", 0x3ea5477c, "." },
  ["FactionDescription:54"] = { "Gli ex abitanti di Gnomeregan, ora in esilio a Forgiardente e schierati tra le file dell'Alleanza.", 0x067f29fe, "." },
  ["FactionDescription:576"] = { "Una delle ultime tribù di mezzorsi non corrotte, i Mordilegno cercano di preservare le loro tradizioni spirituali e di porre fine alla sofferenza dei loro fratelli.", 0xe2692542, "." },
  ["FactionDescription:577"] = { "Questo insediamento commerciale è gestito dai Goblin del Cartello degli Spargifumo e si trova sul crocevia tra le principali vie commerciali di Fontefredda.", 0xa62dc357, "." },
  ["FactionDescription:589"] = { "Questo piccolo gruppo solitario di Elfi della Notte alleva e addestra le Fiere Glaciali nell'area di Fontefredda.", 0x4f149356, "." },
  ["FactionDescription:59"] = { "I Nani della Fratellanza del Torio dimostrano grandi competenze nella forgiatura di oggetti magici e sono decisi a carpire tutti i segreti del Massiccio Roccianera.", 0xd74f4abb, "." },
  ["FactionDescription:609"] = { "I Druidi del Circolo Cenariano sono i guardiani della natura e dominano le tranquille terre di Radaluna.", 0x09a580e2, "." },
  ["FactionDescription:630"] = { "I devasauri del Cratere di Un'Goro sono incredibilmente letali, ma alcuni sono riusciti ad addomesticarli.", 0x8770841e, "." },
  ["FactionDescription:68"] = { "Guidati da Sylvanas Ventolesto, i Reietti hanno stretto una delicata alleanza con l'Orda e hanno costruito la loro capitale nelle profondità delle Rovine di Lordaeron.", 0xde70e660, "." },
  ["FactionDescription:69"] = { "Questa capitale dell'Alleanza è popolata dagli elfi della notte ed è situata sull'isola di Teldrassil.  È governata da Tyrande Soffiabrezza, Sacerdotessa della Luna.", 0x7c7ef884, "." },
  ["FactionDescription:70"] = { "Un'organizzazione criminale gestita principalmente da Umani che opera principalmente tra le Montagne d'Alterac e le Alture di Colletorto.", 0x039ecfd7, "." },
  ["FactionDescription:72"] = { "Uno degli ultimi bastioni del potere umano, questa capitale dell'Alleanza è governata dal re bambino Anduin Wrynn.", 0x1a805474, "." },
  ["FactionDescription:729"] = { "Il Clan Lupi Bianchi sta cercando di scacciare i Nani del Clan Piccatonante dalla Valle d'Alterac.", 0xb1085726, "." },
  ["FactionDescription:730"] = { "I Nani Piccatonante hanno consolidato la loro dimora nella Valle d'Alterac, dove si trovano in continua lotta contro gli Orchi Lupi Bianchi.", 0xf10b0cba, "." },
  ["FactionDescription:749"] = { "Questi elementali hanno preso dimora nelle isole orientali di Azshara. Sono nemici giurati delle armate di Ragnaros.", 0x6fb36621, "." },
  ["FactionDescription:76"] = { "Fondata da Thrall, la capitale dell'Orda è la patria dei valorosi clan di Orchi che abitano Durotar.", 0x86291572, "." },
  ["FactionDescription:809"] = { "Costituiscono ciò che resta di un gruppo di potenti Elfi che abitavano Maglio Infausto; ancora oggi sono considerati grandi saggi e detentori di incredibili segreti.", 0x63e9a14a, "." },
  ["FactionDescription:81"] = { "Cairne Bloodhoof guida il suo popolo, i fieri Tauren, da questa imponente capitale dell'Orda.", 0xfed3b47e, "." },
  ["FactionDescription:87"] = { "Questi spietati corsari sono la rovina dei commerci marittimi. Nemici giurati dei Goblin della Baia del Bottino.", 0x7ad652c1, "." },
  ["FactionDescription:889"] = { "Feroci Orchi del Clan Cantaguerra, in continua battaglia contro le Sentinelle Alargentea nella Forra dei Cantaguerra.", 0xdfb1cd3c, "." },
  ["FactionDescription:890"] = { "Fedeli difensori di Valtetra, in continua battaglia con i Predoni Cantaguerra nella Forra dei Cantaguerra.", 0xa1c33f03, "." },
  ["FactionDescription:909"] = { "Una fiera itinerante del curioso e dello straordinario.  La si vede spesso nella Foresta di Elwynn e a Mulgore.", 0x4339ac1f, "." },
  ["FactionDescription:910"] = { "Discendenti dello Stormo dei Draghi di Bronzo, sono i guardiani del tempo e sono noti per interessarsi ben poco delle razze mortali.", 0x83782a84, "." },
  ["FactionDescription:92"] = { "Questi Centauri si sono insediati nelle regioni meridionali di Desolanda. Nemici mortali dei Centauri Magram.", 0x1b4b2304, "." },
  ["FactionDescription:93"] = { "Questi Centauri si sono insediati nelle regioni orientali di Desolanda. Nemici mortali dei Centauri Gelkis.", 0xc63dbc46, "." },
  ["FlyoutDescription:248"] = { "Crea un portale che teletrasporta in una grande città i membri del gruppo che lo usano.", 0x2fca8585, "." },
  ["FlyoutDescription:249"] = { "Crea un portale che teletrasporta in una grande città i membri del gruppo che lo usano.", 0x2fca8585, "." },
  ["FlyoutDescription:250"] = { "Ti teletrasporta in una grande città.", 0xe53b14b6, "." },
  ["FlyoutDescription:251"] = { "Ti teletrasporta in una grande città.", 0xe53b14b6, "." },
  ["FlyoutDescription:252"] = { "Le tue resistenze agli incantesimi.", 0xbe79a3f4, "." },
  ["FlyoutDescription:253"] = { "Assumi gli aspetti della natura.", 0x8208bcc8, "." },
  ["FlyoutDescription:257"] = { "La tua competenza con le armi determina la tua efficacia in combattimento: influisce sulla probabilità di colpire, di mettere a segno un colpo critico e di non farti schivare o parare, oltre che sulla riduzione dei danni dei tuoi colpi imprecisi.", 0xea9a871d, "." },
  ["FlyoutDescription:259"] = { "Evoca un demone al comando dello Stregone.", 0x5104a88b, "." },
  ["FlyoutDescription:261"] = { "Ordina all'Imp di lanciare incantesimi.", 0x4bd30cc9, "." },
  ["FlyoutDescription:262"] = { "Assumi una forma diversa.", 0xec60c366, "." },
  ["FlyoutDescription:263"] = { "Conferisce Benedizioni del Castigo ai bersagli amici.", 0x95f6dc0c, "." },
