  ["FlyoutDescription:270"] = { "Attiva un'aura protettiva per il tuo gruppo.", 0x86f23c32, "." },
  ["FlyoutDescription:272"] = { "Benedizioni che hanno effetto su tutti i membri del tuo gruppo della stessa classe.", 0xb94cbb3a, "." },
  ["FlyoutDescription:273"] = { "Benedizioni di breve durata usate per salvare un singolo bersaglio.", 0x58025047, "." },
